-- Dungeon Master's Guide source-backed rules catalog: additional mechanical detail and optional variants.
-- Mechanical summaries are intentionally concise; the supplied sourcebook remains authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg-3.5','dungeon-masters-guide-3-5','Dungeon Master''s Guide','DMG',
        'Wizards of the Coast','dnd','3.5','D&D v.3.5 core Dungeon Master''s Guide, including the official errata appended to the supplied source PDF.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dmg-armor-encumbrance-speed','Armor and Encumbrance Speed','20','movement','table',0,1,NULL,NULL,'Base land speeds are reduced by medium or heavy armor and by medium or heavy loads according to the standard movement table.','["movement","armor","encumbrance","speed"]','{"speed_reductions_ft":{"20":15,"30":20,"40":30,"50":35,"60":40,"70":50,"80":55,"90":60,"100":70}}'),
  ('dmg-flight-stall-recovery','Flight Stall and Recovery','20','movement','rule',0,1,'dmg-three-dimensional-movement',NULL,'A flying creature that fails to maintain its minimum forward speed must land if possible or stall and fall, with later chances to recover from the stall.','["flight","movement","stall"]','{"initial_fall_ft":150,"recovery_reflex_dc":20,"subsequent_fall_ft":300,"recovery_attempt":"each_turn"}'),
  ('dmg-defense-roll-variant','Defense Roll Variant','25','combat','rule',1,0,NULL,NULL,'Instead of a fixed Armor Class result, the defender rolls a d20 and adds the portion of AC above 10; an optional faster form reuses one defense roll against all attacks for that round.','["variant","combat","armor-class","attack-roll"]','{"defense_roll":"1d20 + (AC - 10)","round_reuse_option":true}'),
  ('dmg-clobbered-variant','Clobbered Variant','27','combat','rule',1,0,NULL,NULL,'A creature struck for at least half its current hit points by one blow is clobbered and may take only a standard action on its next turn.','["variant","damage","actions"]','{"trigger_damage_fraction_of_current_hp":0.5,"next_turn_actions":["standard"],"duration_turns":1}'),
  ('dmg-massive-damage-size-variant','Massive Damage by Size Variant','27','combat','table',1,0,NULL,NULL,'The massive-damage threshold can vary by creature size, changing by 10 hit points for each size category away from Medium.','["variant","massive-damage","size"]','{"threshold_hp":{"Fine":10,"Diminutive":20,"Tiny":30,"Small":40,"Medium":50,"Large":60,"Huge":70,"Gargantuan":80,"Colossal":90}}'),
  ('dmg-specific-body-damage-variant','Damage to Specific Areas Variant','27','combat','subsystem',1,0,NULL,NULL,'When a specific body area is injured, actions relying on that area can take a penalty until the wound is treated or healed; an optional Fortitude save can let a character ignore the penalty.','["variant","damage","injury","healing"]','{"action_penalty":-2,"minor_wound_heal_dc":15,"magical_healing_hp_to_clear_minor":1,"rest_days_to_clear_minor":1,"tough_it_out_fort_dc":"10 + damage taken","penalties_stack":false}'),
  ('dmg-weapon-equivalencies-variant','Weapon Equivalencies Variant','27','equipment','table',1,0,NULL,NULL,'Certain differently sized weapons can be treated as equivalent weapon types, allowing proficiency with the equivalent weapon to avoid the normal inappropriate-size penalty.','["variant","weapons","size","proficiency"]','{"equivalency_avoids_size_penalty":true}'),
  ('dmg-instant-kill-variant','Instant Kill Variant','28','combat','rule',1,0,NULL,NULL,'A natural 20 followed by another natural 20 on the critical roll threatens an instant kill; a third roll that would hit the target kills it, unless the target is immune to critical hits.','["variant","critical-hit","instant-kill"]','{"initial_attack_natural":20,"critical_roll_natural":20,"third_roll_must_hit":true,"critical_immunity_applies":true}'),
  ('dmg-softer-critical-hits-variant','Softer Critical Hits Variant','28','combat','table',1,0,NULL,NULL,'Critical hits can be softened by narrowing threat ranges and reducing multipliers, including removing critical hits from weapons that normally threaten only on 20 for ×2.','["variant","critical-hit"]','{"mapping":[{"standard_threat":"20","softer_threat":null,"standard_multiplier":"x2","softer_multiplier":null},{"standard_threat":"19-20","softer_threat":"20","standard_multiplier":"x3","softer_multiplier":"x2"},{"standard_threat":"18-20","softer_threat":"19-20","standard_multiplier":"x4","softer_multiplier":"x3"}]}'),
  ('dmg-critical-misses-variant','Critical Misses Variant','28','combat','rule',1,0,NULL,NULL,'On a natural 1 attack roll, the attacker makes a Dexterity check; failure produces a fumble consequence chosen by the DM.','["variant","attack-roll","fumble"]','{"trigger_natural":1,"dexterity_check_dc":10}'),
  ('dmg-weapon-size-increase','Increasing Weapon Damage by Size','28','combat','table',0,1,'dmg-weapon-size-damage',NULL,'Weapon damage dice increase along the Dungeon Master''s Guide size-damage progression when a weapon is made for larger creatures.','["weapons","size","damage","table"]','{"one_size_larger":{"1d2":"1d3","1d3":"1d4","1d4":"1d6","1d6":"1d8","1d8":"2d6","1d10":"2d8","1d12":"3d6","2d4":"2d6","2d6":"3d6","2d8":"3d8","2d10":"4d8"}}'),
  ('dmg-weapon-size-decrease','Decreasing Weapon Damage by Size','28','combat','table',0,1,'dmg-weapon-size-damage',NULL,'Weapon damage dice decrease along the Dungeon Master''s Guide size-damage progression when a weapon is made for smaller creatures.','["weapons","size","damage","table"]','{"one_size_smaller":{"1d2":"1","1d3":"1d2","1d4":"1d3","1d6":"1d4","1d8":"1d6","1d10":"1d8","1d12":"1d10","2d4":"1d6","2d6":"1d10","2d8":"2d6","2d10":"2d8"}}'),
  ('dmg-very-small-creatures','Very Small Creatures in Melee','29','combat','rule',0,1,'dmg-big-little-creatures',NULL,'Fine, Diminutive, and Tiny creatures normally have no natural reach and must enter an opponent''s square to make a melee attack unless using a weapon that grants reach.','["size","reach","melee"]','{"sizes":["Fine","Diminutive","Tiny"],"natural_reach_ft":0,"must_enter_target_square":true,"entry_usually_provokes_aoo":true}'),
  ('dmg-size-space-sharing','Sharing Squares by Size Difference','29','combat','rule',0,1,'dmg-big-little-creatures',NULL,'Creatures whose sizes differ by at least three categories can occupy the same square under the creature-size combat rules.','["size","space","grid"]','{"minimum_size_category_difference":3}'),
  ('dmg-squeezing','Squeezing through Narrow Spaces','29','movement','rule',0,1,'dmg-big-little-creatures',NULL,'A creature can squeeze through a space at least half as wide as its normal space, moving more slowly and taking attack and Armor Class penalties.','["movement","squeezing","size"]','{"minimum_width_fraction":0.5,"movement_cost_multiplier":2,"attack_penalty":-4,"ac_penalty":-4}'),
  ('dmg-delineating-tasks','Delineating Skill Tasks','30','checks','guidance',0,1,'dmg-skill-check-dc-adjudication',NULL,'Call for a new check when a character undertakes a distinct task, circumstances materially change, or the check concerns a different opposing group or target.','["skills","checks","adjudication"]','{}'),
  ('dmg-degrees-of-success','Degrees of Success','32','checks','guidance',0,1,'dmg-skill-check-dc-adjudication',NULL,'For checks where extra success matters, exceeding the DC by a substantial margin can yield additional information or a better result.','["skills","checks","degrees-of-success"]','{"example_margins":[10,20]}'),
  ('dmg-degrees-of-failure','Degrees of Failure','32','checks','guidance',0,1,'dmg-skill-check-dc-adjudication',NULL,'For risky checks, failing by a significant margin can produce a worse consequence than an ordinary failure when the governing rule or situation supports it.','["skills","checks","degrees-of-failure"]','{"common_severe_failure_margin":5}'),
  ('dmg-take-10-long-tasks','Taking 10 for Repetitive Safe Tasks','33','checks','guidance',0,1,'dmg-skill-check-dc-adjudication',NULL,'When a repetitive task is safe enough to take 10, resolve the repeated routine at the take-10 result instead of rolling the same check over and over.','["skills","take-10","pacing"]','{"take_10":true}'),
  ('dmg-skills-different-abilities-variant','Skills with Different Abilities Variant','33','checks','rule',1,0,'dmg-skill-check-dc-adjudication',NULL,'When the circumstances justify it, a skill check can use the skill''s ranks with a different ability modifier than the skill normally uses.','["variant","skills","abilities"]','{"alternate_ability_modifier_allowed":true}'),
  ('dmg-save-vs-check','Saving Throw versus Check','34','checks','guidance',0,1,'dmg-saving-throws-adjudication',NULL,'Use a check when a creature actively attempts a task and a saving throw when it reacts to avoid or resist an effect; saving throws also scale with character level.','["saving-throws","checks","adjudication"]','{}'),
  ('dmg-save-dc-formulas','Saving Throw DC Formulas','34','checks','rule',0,1,'dmg-saving-throws-adjudication',NULL,'Spell and monster-ability saving throw DCs use the standard formulas, while miscellaneous effects are commonly assigned a DC from 10 to 20 with 15 as the default.','["saving-throws","dc","spells","monsters"]','{"spell_dc":"10 + spell level + casting ability modifier","monster_ability_dc":"10 + 1/2 monster HD + relevant ability modifier","misc_dc_min":10,"misc_dc_max":20,"misc_default_dc":15}'),
  ('dmg-critical-check-result-variant','Critical Success or Failure on Checks Variant','34','checks','rule',1,0,'dmg-skill-check-dc-adjudication',NULL,'A natural 20 followed by a second successful check can be treated as a critical success, while a natural 1 followed by a second failure can become a critical failure; taking 10 or 20 does not trigger this variant.','["variant","skills","checks","critical"]','{"critical_success":{"trigger_natural":20,"second_check":"must_succeed"},"critical_failure":{"trigger_natural":1,"second_check":"must_fail"},"disabled_when":["take_10","take_20"]}'),
  ('dmg-encounter-difficulty-mix','Recommended Encounter Difficulty Mix','49','encounters','table',0,1,'dmg-encounter-difficulty',NULL,'A typical adventure mixes encounters across easy, conditional-easy, challenging, very difficult, and overpowering categories rather than matching party level every time.','["encounters","difficulty","el","table"]','{"recommended_percent":{"easy":10,"easy_if_handled_properly":20,"challenging":50,"very_difficult":15,"overpowering":5},"el_relation":{"easy":"lower than party","challenging":"equal to party","very_difficult":"party +1 to +4","overpowering":"party +5 or more"}}'),
  ('dmg-challenging-encounter-resources','Challenging Encounter Resource Expectation','49','encounters','guidance',0,1,'dmg-encounter-difficulty',NULL,'An encounter whose EL equals party level is expected to consume about one fifth of the party''s resources, so roughly four such encounters can substantially deplete a party.','["encounters","resources","el"]','{"expected_resource_fraction":0.2,"approx_challenging_encounters_before_low_resources":4}'),
  ('dmg-quicksand','Quicksand','88','hazards','rule',0,1,'dmg-marsh-terrain',NULL,'Quicksand can be spotted before entry with Survival, requires Swim checks to tread or move, can pull failed swimmers under, and supports a Strength-based rescue procedure.','["hazards","marsh","quicksand","swim"]','{"spot_survival_dc":8,"tread_swim_dc":10,"move_5ft_swim_dc":15,"sink_on_failure_margin":5,"surface_swim_dc":15,"surface_dc_increase_per_submerged_round":1,"rescue_strength_dc":15,"victim_hold_strength_dc":10,"rescue_distance_ft":5}'),
  ('dmg-forest-fire','Forest Fire','87','hazards','subsystem',0,1,'dmg-forest-terrain',NULL,'A forest fire combines advancing flames, heat damage, catching fire, and smoke inhalation, with severe penalties for heavy clothing or armor.','["hazards","forest","fire","smoke","heat"]','{"leading_edge_speed_ft_per_round_example":120,"burn_duration_minutes":"2d4 * 10","hot_air_damage_per_round":"1d6 lethal","heat_save_interval_rounds":5,"heat_fort_dc":15,"heat_dc_increase_per_previous_check":1,"heat_failure_damage":"1d4 nonlethal","heavy_clothing_or_armor_save_penalty":-4}'),
  ('dmg-fast-moving-water','Fast-Moving Water','304','environment','rule',0,1,'dmg-aquatic-terrain',NULL,'Fast water requires a Swim or Strength check to avoid being swept along; even successful movement through dangerous current can cause damage, especially over rocks or cascades.','["water","environment","hazards","swim"]','{"swim_or_strength_dc":15,"successful_round_damage":"1d3 nonlethal","rocks_or_cascades_round_damage":"1d6 lethal"}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dmg-3.5-rule-' || d.slug, 'dmg-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r
  WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
